  for (const lines of [[], undefined, [line(-1)], [line(1.5)], [line(100, 0)], [line(100, 1.5)], [null], [line(2 ** 53)]])
    assert.throws(() => priceOrder({ lines }), /invalid_order/, JSON.stringify(lines));
});
